    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            1'b1: begin  // Slave 0 (64b)
                fub_axi_awready = wrgen3_64b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Single-outstanding-target: hold off a new AW while writes
        // to a different slave are in flight (see aw_gate_ok).
        if (!aw_gate_ok) fub_axi_awready = 1'b0;
    end

    // W-ready MUX (FIFO-tracked w_slave_select — awaddr has already reverted by W phase)
    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            1'b1: begin  // Slave 0 (64b)
                fub_axi_wready = wrgen3_64b_wready;
            end
            default: begin
                // No active W transaction
            end
        endcase
    end

    // Write response MUX (B channel - uses b_slave_select FIFO head)
    always_comb begin
        fub_axi_bid = 8'd0;
        fub_axi_bresp = 2'b00;
        fub_axi_bvalid = 1'b0;

        case (b_slave_select)
            1'b1: begin  // Slave 0 (64b)
                fub_axi_bid = wrgen3_64b_b.id;
                fub_axi_bresp = wrgen3_64b_b.resp;
                fub_axi_bvalid = wrgen3_64b_bvalid;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end

